import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_ops_cpp_source = """
torch::Tensor fused_ops_cuda(torch::Tensor input, torch::Tensor scale1, torch::Tensor bias, torch::Tensor scale2);
"""

fused_ops_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_scale_pool_bias_scale_kernel(
    const float* input, float scale1, const float* bias, float scale2, float* output,
    int B, int C, int D, int H, int W,
    int out_D, int out_H, int out_W) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = B * C * out_D * out_H * out_W;
    if (idx >= total_elements) return;

    int b = idx / (C * out_D * out_H * out_W);
    int rem = idx % (C * out_D * out_H * out_W);
    int c = rem / (out_D * out_H * out_W);
    rem = rem % (out_D * out_H * out_W);
    int d = rem / (out_H * out_W);
    rem = rem % (out_H * out_W);
    int h = rem / out_W;
    int w = rem % out_W;

    float sum = 0.0f;
    int count = 0;

    #pragma unroll
    for (int di = 0; di < 2; di++) {
        #pragma unroll
        for (int hi = 0; hi < 2; hi++) {
            #pragma unroll
            for (int wi = 0; wi < 2; wi++) {
                int in_d = d*2 + di;
                int in_h = h*2 + hi;
                int in_w = w*2 + wi;

                if (in_d < D && in_h < H && in_w < W) {
                    int in_idx = b * C * D * H * W +
                                c * D * H * W +
                                in_d * H * W +
                                in_h * W +
                                in_w;
                    sum += input[in_idx] * scale1;
                    count++;
                }
            }
        }
    }

    float avg = count > 0 ? sum / count : 0.0f;
    output[idx] = (avg + bias[c]) * scale2;
}

torch::Tensor fused_ops_cuda(
    torch::Tensor input, torch::Tensor scale1, torch::Tensor bias, torch::Tensor scale2) {

    input = input.contiguous();
    auto B = input.size(0);
    auto C = input.size(1);
    auto D = input.size(2);
    auto H = input.size(3);
    auto W = input.size(4);

    int out_D = D / 2;
    int out_H = H / 2;
    int out_W = W / 2;

    auto output = torch::empty({B, C, out_D, out_H, out_W}, input.options());

    int total_elements = B * C * out_D * out_H * out_W;
    int threads = 256;
    int blocks = (total_elements + threads - 1) / threads;

    float scale1_val = scale1.item<float>();
    float scale2_val = scale2.item<float>();

    fused_scale_pool_bias_scale_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(), scale1_val, bias.data_ptr<float>(), scale2_val,
        output.data_ptr<float>(), B, C, D, H, W, out_D, out_H, out_W);

    return output;
}
"""

fused_ops = load_inline(
    name='fused_ops',
    cpp_sources=fused_ops_cpp_source,
    cuda_sources=fused_ops_source,
    functions=['fused_ops_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, scale1, scale2, bias_shape):
        super(ModelNew, self).__init__()
        self.conv_transpose = nn.ConvTranspose3d(in_channels, out_channels, kernel_size, stride, padding)
        self.scale1 = nn.Parameter(torch.tensor(scale1))
        self.bias = nn.Parameter(torch.randn(bias_shape).squeeze())
        self.scale2 = nn.Parameter(torch.tensor(scale2))
        self.fused_ops = fused_ops

    def forward(self, x):
        x = self.conv_transpose(x)
        x = self.fused_ops.fused_ops_cuda(x, self.scale1, self.bias, self.scale2)
        return x
